def topo_sort(graph):
    visited = set()
    path = set()
    order = []

    def dfs(node):
        if node in path:
            return False
        if node in visited:
            return True
        path.add(node)
        for dep in graph.get(node, []):
            if not dfs(dep):
                return False
        path.remove(node)
        visited.add(node)
        order.append(node)
        return True

    for node in graph:
        if node not in visited:
            if not dfs(node):
                return None
    return order
```

