def normalize(path):
    if not path:
        return '.'

    is_absolute = path.startswith('/')

    # Split by '/' and filter out empty strings (which represent duplicate slashes or leading/trailing slashes)
    parts = [p for p in path.split('/') if p != '']

    # Resolve '.' and '..'
    resolved = []
    for part in parts:
        if part == '.':
            continue
        elif part == '..':
            if resolved and resolved[-1] != '..':
                resolved.pop()
            elif not is_absolute:
                resolved.append(part)
        else:
            resolved.append(part)

    # Reconstruct the path
    if is_absolute:
        if not resolved:
            return '/'
        return '/' + '/'.join(resolved)
    else:
        if not resolved:
            return '.'
        return '/'.join(resolved)
```

