def count_paths(m, n):
    if m <= 0 or n <= 0:
        return 0

    # Create a 2D DP table
    dp = [[0] * n for _ in range(m)]

    # Initialize the first row and first column
    for i in range(m):
        dp[i][0] = 1
    for j in range(n):
        dp[0][j] = 1

    # Fill the rest of the table
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[m-1][n-1]
```

