function debounceCount(fn, ms) {
  let timer = null;
  let callCount = 0;

  const call = function(...args) {
    callCount++;
    if (timer) {
      clearTimeout(timer);
    }
    timer = setTimeout(() => {
      fn.apply(this, args);
      timer = null;
    }, ms);
  };

  const flush = function() {
    if (timer) {
      clearTimeout(timer);
      timer = null;
      fn();
    }
  };

  return { call, flush };
}

module.exports = debounceCount;
