function parseQuery(qs) {
  if (typeof qs !== 'string' || qs.length === 0) {
    return {};
  }

  const result = {};

  // Remove leading '?' or '#' if present
  if (qs[0] === '?' || qs[0] === '#') {
    qs = qs.substring(1);
  }

  const pairs = qs.split('&');

  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i];
    const eqIndex = pair.indexOf('=');

    let key, value;

    if (eqIndex === -1) {
      // Key with no value
      key = decodeURIComponent(pair.replace(/\+/g, ' '));
      value = '';
    } else {
      key = decodeURIComponent(pair.substring(0, eqIndex).replace(/\+/g, ' '));
      value = decodeURIComponent(pair.substring(eqIndex + 1).replace(/\+/g, ' '));
    }

    if (result.hasOwnProperty(key)) {
      // If key already exists, convert to array or push to existing array
      if (Array.isArray(result[key])) {
        result[key].push(value);
      } else {
        result[key] = [result[key], value];
      }
    } else {
      result[key] = value;
    }
  }

  return result;
}

module.exports = { parseQuery };
