function rotateArray(arr, k) {
    if (arr.length === 0) return [];

    const n = arr.length;
    // Handle negative k and k larger than length
    let effectiveK = ((k % n) + n) % n;

    // If no rotation needed, return a copy
    if (effectiveK === 0) return [...arr];

    // Rotate right: last k elements move to front
    const splitIndex = n - effectiveK;
    return [...arr.slice(splitIndex), ...arr.slice(0, splitIndex)];
}

module.exports = rotateArray;
