export function debounceState(): { pending: boolean; mark(): void; clear(): void } {
  let pending = false;
  let timer: ReturnType<typeof setTimeout> | null = null;

  return {
    get pending(): boolean {
      return pending;
    },
    mark(): void {
      pending = true;
      if (timer !== null) {
        clearTimeout(timer);
      }
      timer = setTimeout(() => {
        pending = false;
        timer = null;
      }, 0);
    },
    clear(): void {
      pending = false;
      if (timer !== null) {
        clearTimeout(timer);
        timer = null;
      }
    }
  };
}
