    return true;
  }
};

/**
 * DELETE /api/v1/orders/{id}
 *
 * - 204 No Content: Order successfully deleted.
 * - 404 Not Found: Order does not exist.
 * - 409 Conflict: Order has already shipped (or delivered).
 */
router.delete('/api/v1/orders/:id', async (req, res) => {
  const { id } = req.params;

  try {
    // 1. Find the order
    const order = await orderRepo.findById(id);

    // 2. Handle 404: Order not found
    if (!order) {
      return res.status(404).json({
        error: 'Order not found',
        message: `No order exists with ID: ${id}`
      });
    }

    // 3. Handle 409: Order has already shipped (or delivered)
    // Adjust status check based on your business rules
    if (order.status === 'shipped' || order.status === 'delivered') {
      return res.status(409).json({
        error: 'Conflict',
        message: `Cannot delete order ${id}. Order has already been ${order.status}.`
      });
    }

    // 4. Proceed with deletion
    await orderRepo.delete(id);

    // 5. Return 204 No Content (no body)
    return res.status(204).send();

